SELECT count(*) AS count_after_savepoints, min(x) AS min_x, max(x) AS max_x, sum(x) AS sum_x, sum(CASE WHEN x%10=0 THEN 1 ELSE 0 END) AS base_rows, sum(CASE WHEN x%10=1 THEN 1 ELSE 0 END) AS suffix_one_rows, sum(CASE WHEN x%10=2 THEN 1 ELSE 0 END) AS suffix_two_rows, min(length(y)) AS min_y_length, max(length(y)) AS max_y_length, sum(CASE WHEN y=printf('%04d%.800c',x/10,'*') THEN 1 ELSE 0 END) AS matching_payloads FROM t1;